14	import java.util.Map;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
25	    @Mapping(target = "locality", expression = "java(locality(owner))")
26	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
27	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
28	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
29	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
30	    @Mapping(target = "bulkSignupWarning", ignore = true)
31	    OwnerDto toOwnerDto(Owner owner);
32	
33	    /**
34	     * The owner's age band, derived at read time from {@code birthDate} relative to the
35	     * {@code registrationDate}: {@code MINOR} under 18, {@code ADULT} from 18 to 64 and
36	     * {@code SENIOR} at 65 or older. Null when the owner or its {@code birthDate} (or the
37	     * {@code registrationDate} it is measured against) is absent, so the field is simply
38	     * omitted for owners without a birth date.
39	     */
40	    default String ageBand(Owner owner) {
41	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
42	            return null;
43	        }
44	        int years = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
45	        if (years < 18) {
46	            return "MINOR";
47	        }
48	        if (years < 65) {
49	            return "ADULT";
50	        }
51	        return "SENIOR";
52	    }
53	
54	    /**
55	     * A single Luhn check digit (0-9) computed at read time over the digits contained in the
56	     * owner's customerCode. Non-digit characters (the hyphen and letters in '<REGION>-<HASH8>')
57	     * are skipped. Null when the owner or its customerCode is absent.
58	     */
59	    default Integer checkDigit(Owner owner) {
60	        if (owner == null || owner.getCustomerCode() == null) {
61	            return null;
62	        }
63	        String code = owner.getCustomerCode();
64	        int sum = 0;
65	        boolean dbl = true;
66	        for (int i = code.length() - 1; i >= 0; i--) {
67	            char c = code.charAt(i);
68	            if (c < '0' || c > '9') {
69	                continue;
70	            }
71	            int d = c - '0';
72	            if (dbl) {
73	                d *= 2;
74	                if (d > 9) {
75	                    d -= 9;
76	                }
77	            }
78	            sum += d;
79	            dbl = !dbl;
80	        }
81	        return (10 - (sum % 10)) % 10;
82	    }
83	
84	    /**
85	     * The owner's preferred contact channel, derived at read time: {@code EMAIL}
86	     * when an email address is present, otherwise {@code PHONE}.
87	     */
88	    default String contactPreference(Owner owner) {
89	        if (owner == null) {
90	            return null;
91	        }
92	        String email = owner.getEmail();
93	        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
94	    }
95	
96	    /** Fixed city-to-region table used to derive an owner's locality at read time. */
97	    Map<String, String> CITY_REGION = Map.of(
98	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
99	
100	    /** Region to its inclusive 4-digit postcode range {low, high}. */
101	    Map<String, int[]> REGION_POSTCODES = Map.of(
102	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
103	
104	    /** Fixed region-to-timezone table, mapping each region to its IANA timezone name. */
105	    Map<String, String> REGION_TIMEZONE = Map.of(
106	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
107	
108	    /**
109	     * The owner's locality, derived at read time from the region-and-hash identity: the REGION
110	     * prefix of the {@code customerCode} (everything before the first hyphen). That region was
111	     * itself derived at write time from the postcode (preferred) or city, defaulting to
112	     * {@code UNKNOWN}, so reading it back keeps locality and the identity in lock-step.
113	     *
114	     * <p>Owners predating the region-and-hash identity (e.g. seed data with no customerCode) fall
115	     * back to the historical read-time derivation: postcode preferred, then city, then
116	     * {@code UNKNOWN}.
117	     */
118	    default String locality(Owner owner) {
119	        if (owner == null) {
